CREATE TABLE inventory_items (restaurant_id uuid NOT NULL REFERENCES restaurants(id), id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, unit text NOT NULL, stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), reorder_level integer NOT NULL DEFAULT 0 CHECK(reorder_level>=0), PRIMARY KEY(restaurant_id,id), UNIQUE(restaurant_id,name));
CREATE TABLE recipes (restaurant_id uuid NOT NULL, menu_id text NOT NULL, inventory_id uuid NOT NULL, full_amount integer NOT NULL CHECK(full_amount>0), half_amount integer CHECK(half_amount>0), addon_amount integer NOT NULL DEFAULT 0 CHECK(addon_amount>=0), PRIMARY KEY(restaurant_id,menu_id,inventory_id), FOREIGN KEY(restaurant_id,menu_id) REFERENCES menu_items(restaurant_id,id), FOREIGN KEY(restaurant_id,inventory_id) REFERENCES inventory_items(restaurant_id,id));
CREATE TYPE inventory_movement AS ENUM ('purchase','waste','adjustment','order');
CREATE TABLE inventory_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL, inventory_id uuid NOT NULL, order_id uuid, delta integer NOT NULL CHECK(delta<>0), kind inventory_movement NOT NULL, note text NOT NULL DEFAULT '', actor_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(restaurant_id,inventory_id) REFERENCES inventory_items(restaurant_id,id), FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id));
CREATE UNIQUE INDEX once_order_ingredient ON inventory_transactions(restaurant_id,order_id,inventory_id) WHERE order_id IS NOT NULL;
